globalCss:
/* Ink Wash */
:root {
  --ink-bg: #f8f5f0;
  --ink-surface: #f3efe8;
  --ink-text: #2c2c2c;
  --ink-muted: #a89279;
  --ink-moss: #6b7b6e;
  --ink-sand: #c4b9a8;
  --ink-border: #2c2c2c;
}
@keyframes ink-wash-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes ink-wash-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.ink-wash-card {
  position: relative;
  overflow: hidden;
}

.ink-wash-card::before {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 0.3s ease;
  background: linear-gradient(135deg, rgba(44, 44, 44, 0.05), transparent);
  pointer-events: none;
}

.ink-wash-card:hover::before {
  opacity: 1;
}

.ink-wash-gradient {
  background: linear-gradient(135deg, #2c2c2c, #6b7b6e);
}

.ink-wash-gradient-text {
  background: linear-gradient(135deg, #2c2c2c, #6b7b6e);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.ink-wash-frosted {
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  background: rgba(44, 44, 44, 0.08);
}

.ink-wash-accent-corner {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 2rem), calc(100% - 2rem) 100%, 0 100%);
}

.ink-wash-animate-in {
  animation: ink-wash-fade-in 0.5s ease-out both;
}
